export type Distro = (typeof DISTROS)[number];
export type DistroId = Distro["id"];

/** The values each profile fact can take. */
export const PROFILE_VALUES = {
	desktop: ["plasma", "lxqt"],
	init: ["systemd", "openrc"],
	kernel_line: ["lts", "latest"],
	libc: ["glibc", "musl"],
	packages: ["rpm", "apk"],
	privilege: ["sudo", "doas"],
} as const;

/** The /etc/os-release field each fact is written to on the image. */
export const OS_RELEASE_FIELDS = {
	desktop: "REC_DESKTOP",
	init: "REC_INIT",
	kernel_line: "REC_KERNEL_LINE",
	libc: "REC_LIBC",
	packages: "REC_PACKAGES",
	privilege: "REC_PRIVILEGE",
} as const;

/** The group whose members become root through the privilege tool. */
export const ADMIN_GROUP = "wheel" as const;

export type Profile = {
	-readonly [K in keyof typeof PROFILE_VALUES]: (typeof PROFILE_VALUES)[K][number];
};

/** The value of `field` in the text of an /etc/os-release (quotes removed; the last setting wins). */
export function osReleaseValue(osRelease: string, field: string): string | null {
	let found: string | null = null;
	for (const line of osRelease.split("\n")) {
		const trimmed = line.trim();
		if (!trimmed.startsWith(`${field}=`)) continue;
		const value = trimmed
			.slice(field.length + 1)
			.trim()
			.replace(/^["']|["']$/g, "")
			.trim();
		if (value) found = value;
	}
	return found;
}

/** One profile fact from an os-release; null when it is missing or not a known value. */
export function osReleaseFact<K extends keyof Profile>(
	osRelease: string,
	fact: K,
): Profile[K] | null {
	const value = osReleaseValue(osRelease, OS_RELEASE_FIELDS[fact]);
	const known = PROFILE_VALUES[fact] as readonly string[];
	return value !== null && known.includes(value) ? (value as Profile[K]) : null;
}

/** The variant whose os-release ID is `osId`, if there is one. */
export function distroByOsId(osId: string): Distro | undefined {
	return DISTROS.find((distro) => distro.osId === osId);
}
